/* Read-only, source-scoped explanations beside campaign controls. */
(function(){'use strict';
const R=()=>window.RULES_DATA||{},D=()=>window.MMCampaignFieldGuideData||{},E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),L=(en,ko,tag='span')=>`<${tag} data-i18n-en="${E(en)}" data-i18n-ko="${E(ko)}">${E(en)}</${tag}>`,P=pair=>window.MMRuleTerms?.prose(...pair,{edition:'n26'})||L(...pair,'p');
const icon='<svg viewBox="0 0 24 24" width="17" height="17" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="12" cy="12" r="9"/><path d="M12 10v7M12 7v.1"/></svg>';
const verified=r=>r?.source_verified&&String(r.edition_slug||r.edition).toLowerCase()==='n26';
function supported(c){return String(c?.edition).toLowerCase()==='n26'&&typeof cpCampaignType==='function'&&cpCampaignType(c)?.id==='official-003-campaign-necromunda-campaign';}
function refs(entry,c){if(!supported(c))return [];return(entry.refs||[]).map(ref=>{const[kind,id]=Array.isArray(ref)?ref:['coreRules',ref];const row=(R()[kind]||[]).find(r=>r.id===id&&verified(r));return row?{kind,row}:null;}).filter(Boolean);}
function button(key,caption=null){const entry=D()[key];if(!entry)return '';const labelEn=entry.title[0]+' — explanation and example',labelKo=entry.title[1]+' 설명·예시 보기';return `<button type="button" class="${caption?'ccg-explain-button':'ccg-icon'}" data-campaign-help="${key}" aria-haspopup="dialog" aria-label="${E(labelEn)}" data-i18n-en-aria-label="${E(labelEn)}" data-i18n-ko-aria-label="${E(labelKo)}">${caption?L(...caption):icon}</button>`;}
function term(key,pair){return `<button type="button" class="ccg-term" data-campaign-help="${key}" aria-haspopup="dialog">${L(...pair)}</button>`;}
function open(key,{activator,c=typeof campaign==='function'?campaign():null}={}){const entry=D()[key];if(!entry||!c)return false;const rules=refs(entry,c),source=supported(c),prose=pair=>source?P(pair):L(...pair,'p'),when=!source&&entry.mode!=='app'?['Use the corresponding step for your selected campaign; its own edition and conditions determine the game rule.','선택한 캠페인의 해당 진행 단계에서 사용하며 게임 규칙은 그 판본과 캠페인 조건을 확인하세요.']:entry.when,showExample=!!entry.example&&(source||entry.mode==='app'&&!entry.refs.length);const body=`<div class="ccg-help" data-campaign-help-content="${key}"><span class="ccg-help-badge">${entry.mode==='app'?L('App feature','앱 기능'):source?L('N26 rules & app workflow','N26 규칙·앱 사용법'):L('App workflow','앱 사용법')}</span><section class="ccg-help-intro"><h3>${L('What is this?','어떤 항목인가요?')}</h3>${prose(entry.what)}</section><section class="ccg-help-intro"><h3>${L('When do I use it?','언제 사용하나요?')}</h3>${prose(when)}</section>${entry.flow?.length?`<ol class="ccg-flow">${entry.flow.map(pair=>`<li>${L(...pair)}</li>`).join('')}</ol>`:''}${source&&entry.sections?.length?`<div class="ccg-workflow-sections">${entry.sections.map((section,i)=>`<details class="ccg-fold" data-battle-guide-step="${i}"><summary>${L(...section.title)}</summary><div class="ccg-fold-body">${section.rule?`<h4>${L('Rule','룰상 절차')}</h4>${prose(section.rule)}`:''}${section.app?`<h4>${L('In this app','앱에서 하는 일')}</h4>${prose(section.app)}`:''}${section.example?`<h4>${L('Example','상황 예시')}</h4>${prose(section.example)}`:''}</div></details>`).join('')}</div>`:''}${rules.length?`<details class="ccg-fold" data-ccg-fold="rules"><summary>${L('Rulebook rules for this item','룰북 근거와 적용 조건')} <small>N26 · ${rules.length}</small></summary><div class="ccg-fold-body">${rules.map(({kind,row})=>`<article class="ccg-quote"><h4><button type="button" data-ccg-ref="${E(row.id)}" data-ccg-kind="${kind}">${L(row.name,row.name_ko||row.name)}</button></h4><blockquote>${prose([row.description_en||row.description,row.description||row.description_en])}</blockquote></article>`).join('')}</div></details>`:''}${showExample?`<details class="ccg-fold" data-ccg-fold="example"><summary>${L('Worked example & common confusion','상황 예시·헷갈리기 쉬운 점')}</summary><div class="ccg-fold-body">${prose(entry.example)}</div></details>`:''}</div>`;window.MMRuleReference.openContext(entry.title[0],body,{nameKo:entry.title[1],activator,nested:!!document.querySelector('.mmrr-overlay')});document.querySelector('.mmrr-dialog')?.classList.add('ccg-dialog');return true;}
const norm=s=>String(s||'').replace(/[ⓘℹ\s]/g,'').toLowerCase();
function helpOn(host,key){if(!host||!D()[key])return;host.querySelectorAll('[data-mm-help-auto="yes"]').forEach(n=>n.remove());if(host.querySelector('[data-campaign-help]'))return;host.insertAdjacentHTML('beforeend',button(key));}
function headingHelp(root){const map=[['Gangs & Players','갱 & 플레이어','gangs'],['Captured Fighters','생포된 파이터','captives'],['Territories','영토','territories'],['Battle Sessions','전투 세션','sessions'],['Battles','전투','reports'],['Campaign Pack','캠페인 팩','pack'],['Map','지도','map'],['Triumphs','트라이엄프','triumphs'],['Resources','자원','resources'],['Allegiances','소속 진영','allegiance']];for(const h of root.querySelectorAll('h2')){if(h.closest('.cp-rich-content,[data-user-text],[contenteditable]'))continue;const text=norm(h.textContent),found=map.find(([en,ko])=>[norm(en),norm(ko),norm(window.UKI18n?.t(en,'ko'))].includes(text));if(found){h.removeAttribute('data-i18n-en');h.removeAttribute('data-i18n-ko');h.removeAttribute('data-i18n-catalog-name');h.innerHTML=L(found[0],found[1])+button(found[2]);}}}
function headerHelp(root){const head=root.querySelector('.cp-campaign-header');if(!head)return;head.classList.add('ccg-header');for(const p of head.querySelectorAll('.entity-meta')){const text=p.textContent.trim();if(/^(Arbitrator|아비트레이터)\s*:/.test(text))helpOn(p,'arbitrator');else if(/^(Trading Post|거래소)\s*:/.test(text))helpOn(p,'trading');else if(/^(Type|유형)\s*:/.test(text)){const current=p.querySelector('[data-cp="campaign-type-info"]');if(current){current.dataset.campaignHelp='type';current.classList.add('ccg-icon');current.innerHTML=icon;current.setAttribute('aria-label','Campaign type — explanation');current.dataset.i18nEnAriaLabel='Campaign type — explanation';current.dataset.i18nKoAriaLabel='캠페인 유형 설명 보기';}else p.querySelector('strong')?.insertAdjacentHTML('afterend',button('type'));p.insertAdjacentHTML('beforeend',button('phase'));}}
 const facts=['players','territories','gangs','reports'];[...head.querySelectorAll('.entity-facts>span')].forEach((node,i)=>helpOn(node,facts[i]));
 for(const b of head.querySelectorAll('button')){const text=b.textContent.trim();if(/^Share\s*&\s*Invite$/.test(text)||/^공유\s*&\s*Invite$/.test(text)){b.innerHTML=L('Share & Invite','공유·초대');}if(b.matches('[data-enrollment-open]'))b.classList.add('ccg-main-action');}
}
function tableTerm(th,key,pair){if(!th)return;for(const attr of ['data-i18n-en','data-i18n-ko','data-i18n-catalog-name'])th.removeAttribute(attr);th.querySelectorAll('[data-mm-help-auto="yes"]').forEach(n=>n.remove());th.innerHTML=term(key,pair);}
function tableHelp(root,c){const map={Gang:['gangs',['Gang','갱']],Type:['gang-type',['Type','유형']],Player:['players',['Player','플레이어']],Allegiance:['allegiance',['Allegiance','소속 진영']],Rating:['rating',['Rating','레이팅']],Wealth:['wealth',['Wealth','자산']],Reputation:['reputation',['Reputation','명성']],Territories:['ownership',['Territories','영토']]};for(const th of [...root.querySelectorAll('.cp-members-scroll thead th')].slice(0,7+(c.allegiances?.length?1:0))){const found=Object.entries(map).find(([en,[,pair]])=>[norm(en),norm(pair[1])].includes(norm(th.textContent)));if(found)tableTerm(th,...found[1]);}
 const edit=root.querySelector('[data-cp="territory-edit"]'),table=edit?.closest('table');if(table){table.classList.add('ccg-territory-table');const heads=[...table.querySelectorAll('thead th')];tableTerm(heads[0],'territories',['Territory','영토']);tableTerm(heads[1],'reference',['Ref.','참고']);tableTerm(heads[2],'income',['Income (cr)','수입 (cr)']);tableTerm(heads[3],'ownership',['Controlled by','통제 갱']);for(const tr of table.querySelectorAll('tbody tr')){const cells=[...tr.children];if(cells.length<5)continue;for(const [i,key,en,ko]of[[1,'reference','Reference card','참고 카드'],[2,'income','Income','수입'],[3,'ownership','Controlled by','통제 갱']]){if(cells[i].querySelector('.ccg-cell-label'))continue;cells[i].insertAdjacentHTML('afterbegin',`<small class="ccg-cell-label">${term(key,[en,ko])}</small>`);}cells[4].classList.add('ccg-territory-actions');}}
 const triumph=root.querySelector('.cp-triumph-rules');if(triumph){const type=typeof cpCampaignType==='function'?cpCampaignType(c):null,rows=(R().campaignTriumphs||[]).filter(r=>verified(r)&&r.campaign_type_id===type?.id);[...triumph.querySelectorAll('tbody tr')].forEach((tr,i)=>{const row=rows[i],td=tr.children[0];if(row&&td)td.innerHTML=`<button class="ccg-term" type="button" data-ccg-ref="${E(row.id)}" data-ccg-kind="campaignTriumphs">${L(row.name,row.name_ko||row.name)}</button>`;});}}
function actionHelp(root,c){if(['battles','session-detail'].includes(data.campaignTab)){const host=root.querySelector('.ccg-banner');if(host)host.insertAdjacentHTML('beforeend',button('battle-workflow',['Battle play guide','전투 진행 가이드']));for(const selector of ['[data-session="new"]','[data-cp="battle-new"]']){const action=root.querySelector(selector);if(action)action.insertAdjacentHTML('beforebegin',button('battle-workflow',['Play guide','진행 가이드']));}}const actions=[['[data-cp="challenge-round"]','challenges'],['[data-enrollment-open]','sharing']];for(const[selector,key]of actions)for(const b of root.querySelectorAll(selector)){if(b.nextElementSibling?.dataset.campaignHelp===key)continue;if(b.matches('[data-enrollment-open]')&&b.closest('.entity-head')){const pair=document.createElement('div');pair.className='ccg-participation-action';b.before(pair);pair.append(b);pair.insertAdjacentHTML('beforeend',button(key));}else b.insertAdjacentHTML('afterend',button(key));}
 for(const b of document.querySelectorAll('.content>.enroll-campaign-actions [data-enrollment-open]'))if(!b.nextElementSibling?.matches('[data-campaign-help]'))b.insertAdjacentHTML('afterend',button('sharing'));
 const group=root.querySelector('#cp-group-territories')?.closest('label');helpOn(group,'groups');
 for(const row of root.querySelectorAll('.cp-battle-row')){const id=row.querySelector('[data-cp="battle-edit"]')?.dataset.id,b=c.battles?.find(b=>b.id===id),h=row.querySelector('h3');if(!h||!b)continue;if(b.challenge&&(!b.name||b.name==='Challenge'))for(const node of [...h.childNodes])if(node.nodeType===3&&node.textContent.trim()==='Challenge'){const span=document.createElement('span');span.innerHTML=L('Challenge','도전');node.replaceWith(span);}helpOn(h,b.challenge?'challenges':'reports');}
 const filters=root.querySelector('.cp-battle-filters');if(filters){const keys=['cycle','scenario','gang','winner'],pairs={cycle:['Cycle','사이클'],scenario:['Scenario','시나리오'],gang:['Gang','갱'],winner:['Winner','승리 갱']};filters.insertAdjacentHTML('beforebegin',`<div class="ccg-filter-label">${L('Find a battle','전투 찾기')}${button('filters')}</div>`);filters.querySelectorAll('[data-cp-filter]').forEach(input=>{const key=input.dataset.cpFilter;if(!keys.includes(key))return;input.setAttribute('aria-label',pairs[key][0]);input.dataset.i18nEnAriaLabel=pairs[key][0];input.dataset.i18nKoAriaLabel=pairs[key][1];if(key==='cycle')input.insertAdjacentHTML('afterend',button('cycle'));});}
}
function decorate(){const c=typeof campaign==='function'?campaign():null,root=document.querySelector('.cp-campaign-page');if(typeof data==='undefined'||data.view!=='campaign'||!c||!root||root.dataset.campaignGuideReady)return;root.dataset.campaignGuideReady='true';root.classList.add('ccg-page');const key=data.campaignTab==='session-detail'?'sessions':D()[data.campaignTab]?data.campaignTab:'members',entry=D()[key];if(entry){const banner=`<aside class="ccg-banner" data-campaign-section-guide="${key}"><div><strong>${L(...entry.title)}</strong>${button(key,['Explanation & example','설명·예시'])}</div><p>${L(...entry.what)}</p></aside>`,tabs=root.querySelector('.icon-tabs');if(tabs)tabs.insertAdjacentHTML('afterend',banner);else root.insertAdjacentHTML('afterbegin',banner);}
 headerHelp(root);headingHelp(root);tableHelp(root,c);actionHelp(root,c);const pack=root.querySelector('.cp-pack');if(pack){pack.classList.add('ccg-pack');const empty=pack.querySelector('.cp-centered');if(empty&&!c.packHtml&&!c.notes)empty.innerHTML=L('Keep schedules, agreed rulings and house rules here. Use Edit to start.','일정·판정 합의·하우스 룰을 여기에 정리하세요. 수정 버튼으로 작성할 수 있습니다.');}
 window.UKI18n?.refresh(root);
}
window.addEventListener('click',e=>{const button=e.target.closest?.('[data-campaign-help],[data-ccg-ref]');if(!button)return;e.preventDefault();e.stopImmediatePropagation();if(button.dataset.ccgRef){const kind=button.dataset.ccgKind||'coreRules',row=(R()[kind]||[]).find(r=>r.id===button.dataset.ccgRef&&verified(r));if(row)window.MMRuleReference?.open(kind,row.id,{edition:'n26',activator:button,nested:!!document.querySelector('.mmrr-overlay')});return;}open(button.dataset.campaignHelp,{activator:button});},true);
const beforeRender=render;render=function(...args){const result=beforeRender.apply(this,args);decorate();return result;};
window.MMCampaignFieldGuide={open,decorate,supported,refs};
})();
